mapper.select:
SELECT
    COUNT(*) as unsettledCount,
    IFNULL(SUM(pay.payprice), 0) as unsettledAmount
FROM t_erp_purchase_form_payment pay
INNER JOIN t_erp_purchase_form_entry entry ON entry.id = pay.formentryid
WHERE pay.acct = #{acct,jdbcType=CHAR}
  AND pay.auditstatus = 1
  AND pay.period_rollover_id IS NULL

  AND pay.opttime >= #{fromDate,jdbcType=DATE}


  AND pay.opttime <= #{toDate,jdbcType=DATE}
